// The analyst name is declared (no login) and sent with every mutation, as the backend requires.
import { useSyncExternalStore } from 'react';

const KEY = 'tarvo-actor';
const listeners = new Set<() => void>();
let current = read();
let prompt: (() => Promise<string>) | null = null;

function read() {
  try { return localStorage.getItem(KEY) || ''; } catch { return ''; }
}

export function getActor() {
  return current.trim();
}

export function setActor(name: string) {
  current = name;
  try { localStorage.setItem(KEY, name); } catch { /* storage may be disabled */ }
  listeners.forEach(listener => listener());
}

export function useActor(): [string, (name: string) => void] {
  const value = useSyncExternalStore(listener => { listeners.add(listener); return () => listeners.delete(listener); }, () => current);
  return [value, setActor];
}

/** Registered by <ActorPromptHost/>: asks for the name once when an action needs it. */
export function registerActorPrompt(fn: (() => Promise<string>) | null) {
  prompt = fn;
}

export async function ensureActor(): Promise<string> {
  const name = getActor();
  if (name) return name;
  if (!prompt) throw new Error('Informe seu nome em “Responsável” antes de registrar uma ação.');
  const entered = (await prompt()).trim();
  if (!entered) throw new Error('Informe seu nome para registrar a ação.');
  setActor(entered);
  return entered;
}
import { useState } from 'react';
import { useQueryClient, type QueryKey } from '@tanstack/react-query';
import { useToast } from '../components/Toast';

/** Runs a mutation with busy state, success toast and cache invalidation; errors become toasts. */
export function useAction() {
  const client = useQueryClient();
  const toast = useToast();
  const [busy, setBusy] = useState<string | null>(null);
  async function run<T>(key: string, fn: () => Promise<T>, options: { success?: string; invalidate?: QueryKey[]; rethrow?: boolean } = {}) {
    setBusy(key);
    try {
      const result = await fn();
      await Promise.all((options.invalidate || []).map(queryKey => client.invalidateQueries({ queryKey })));
      if (options.success) toast.ok(options.success);
      return result;
    } catch (error) {
      if (options.rethrow) throw error;
      toast.error(error);
      return undefined;
    } finally {
      setBusy(null);
    }
  }
  return { run, busy };
}
// Billing/dispute/internal e-mail review. Approval binds to the exact content; any edit invalidates it.
import { useEffect, useState } from 'react';
import { core } from '../api/core';
import type { Email } from '../api/types';
import { dateTimeBR } from '../lib/format';
import { keys, useAppState } from '../state/queries';
import { useAction } from '../state/useAction';
import { Icon } from './Icon';
import { Sheet } from './Overlay';
import { Badge, Callout, Field } from './ui';

export const EMAIL_KIND: Record<Email['kind'], string> = { billing: 'Cobrança', dispute: 'Contestação', internal: 'Interno' };

export function emailStage(email?: Email) {
  if (!email) return { label: 'Proposta', step: 0, tone: 'neutral' as const };
  if (email.stale) return { label: 'Rascunho desatualizado', step: 1, tone: 'warning' as const };
  if (email.status === 'simulated' || email.status === 'sent') return { label: 'Enviada (simulada)', step: 3, tone: 'good' as const };
  if (email.status === 'approved') return { label: 'Aprovada', step: 2, tone: 'info' as const };
  return { label: 'Rascunho', step: 1, tone: 'accent' as const };
}

export function EmailEditor({ emailId, onClose, cnpj }: { emailId: string; onClose: () => void; cnpj?: string }) {
  const { data: state } = useAppState();
  const email = state?.emails.find(item => String(item.id) === String(emailId));
  const { run, busy } = useAction();
  const [form, setForm] = useState({ to: '', subject: '', body: '' });
  useEffect(() => { if (email) setForm({ to: email.to || '', subject: email.subject || '', body: email.body || '' }); }, [email?.id, email?.to, email?.subject, email?.body]);
  if (!state || !email) return null;

  const sent = email.status === 'simulated' || email.status === 'sent';
  const dirty = form.to !== (email.to || '') || form.subject !== email.subject || form.body !== email.body;
  const needsApproval = email.kind !== 'internal';
  const canSend = !email.stale && !dirty && (email.status === 'approved' || !needsApproval) && !!email.to;
  const contacts = state.contacts.filter(contact => contact.enabled && contact.email && (email.kind === 'internal' ? contact.kind === 'internal' : contact.cnpj === cnpj));
  const stage = emailStage(email);
  const refresh = [keys.state];

  return (
    <Sheet
      narrow
      eyebrow={`${EMAIL_KIND[email.kind]} · modo simulação`}
      title={sent ? 'Registro de envio simulado' : 'Revisar e-mail'}
      sub={needsApproval ? 'Nenhuma cobrança sai sem aprovação explícita desta versão.' : 'Aviso interno: dispensa aprovação.'}
      onClose={onClose}
      footer={sent ? <button className="btn" onClick={onClose}>Fechar</button> : <>
        <span className="muted grow" style={{ fontSize: 12 }}>{email.approved_by ? `Aprovado por ${email.approved_by} · ${dateTimeBR(email.approved_at)}` : dirty ? 'Salve antes de aprovar.' : 'Aguardando revisão.'}</span>
        <button className="btn" disabled={!dirty || !!busy} onClick={() => run('save', () => core.saveEmail({ id: email.id, ...form }), { success: 'Rascunho salvo. A aprovação anterior deixa de valer.', invalidate: refresh })}>Salvar</button>
        {needsApproval && (
          <button className="btn dark" disabled={dirty || email.stale || email.status === 'approved' || !form.to || !!busy}
            onClick={() => run('approve', () => core.approveEmail(email.id), { success: 'Versão aprovada. O envio continua simulado.', invalidate: refresh })}>
            <Icon name="check" />Aprovar esta versão
          </button>
        )}
        <button className="btn primary" disabled={!canSend || !!busy}
          onClick={() => run('send', () => core.sendEmail(email.id), { success: 'Envio simulado registrado. Nenhuma mensagem real saiu.', invalidate: refresh })}>
          <Icon name="send" />Simular envio
        </button>
      </>}
    >
      <div className="stack-lg">
        <div className="row wrap">
          <Badge tone={stage.tone} dot>{stage.label}</Badge>
          <span className="muted" style={{ fontSize: 12 }}>Criado {dateTimeBR(email.created_at)}{email.sent_at && ` · simulado ${dateTimeBR(email.sent_at)}`}</span>
        </div>
        {email.stale && <Callout tone="warning" icon="alert">O cálculo mudou depois deste rascunho. Prepare uma nova versão com os valores atuais.</Callout>}
        {sent ? (
          <>
            <dl className="facts">
              <div><dt>Para</dt><dd>{email.to}</dd></div>
              <div><dt>Assunto</dt><dd>{email.subject}</dd></div>
              <div><dt>Aprovado por</dt><dd>{email.approved_by || '—'}</dd></div>
            </dl>
            <pre className="email-body">{email.body}</pre>
          </>
        ) : (
          <>
            <Field label="Destinatário" required help={!form.to ? 'Sem contato cadastrado: informe o e-mail ou cadastre em Cadastros.' : undefined}>
              <input className="input" type="email" value={form.to} onChange={event => setForm({ ...form, to: event.target.value })} placeholder="[EMAIL_REMOVIDO]" />
            </Field>
            {!!contacts.length && (
              <div className="reason-chips">
                {contacts.map(contact => <button key={contact.id} type="button" className="reason-chip" aria-pressed={form.to === contact.email} onClick={() => setForm({ ...form, to: contact.email })}>{contact.name} · {contact.email}</button>)}
              </div>
            )}
            <Field label="Assunto" required><input className="input" value={form.subject} onChange={event => setForm({ ...form, subject: event.target.value })} /></Field>
            <Field label="Mensagem" required><textarea className="textarea" rows={12} value={form.body} onChange={event => setForm({ ...form, body: event.target.value })} /></Field>
          </>
        )}
      </div>
    </Sheet>
  );
}
import { useState, type ReactNode } from 'react';
import type { Status } from '../api/agent';
import { count, dateBR, money, percent, pp, shortHash } from '../lib/format';
import { Icon, type IconName } from './Icon';

type Tone = 'neutral' | 'good' | 'warning' | 'critical' | 'info' | 'gate' | 'accent';

export const STATUS: Record<Status, { label: string; tone: Tone; icon: IconName }> = {
  pending: { label: 'Pendente', tone: 'neutral', icon: 'circle' },
  running: { label: 'Rodando', tone: 'info', icon: 'refresh' },
  done: { label: 'Concluído', tone: 'good', icon: 'check' },
  exceptions: { label: 'Com exceções', tone: 'warning', icon: 'alert' },
  failed: { label: 'Falhou', tone: 'critical', icon: 'x' },
  awaiting_approval: { label: 'Aguardando aprovação', tone: 'gate', icon: 'pause' },
  approved: { label: 'Aprovado', tone: 'good', icon: 'check' },
  rejected: { label: 'Reprovado', tone: 'critical', icon: 'x' },
  skipped: { label: 'Pulado', tone: 'neutral', icon: 'minus' },
};

/** Status is always text + color, never color alone. */
export function StatusBadge({ status, label, size }: { status: Status; label?: string; size?: 'lg' }) {
  const meta = STATUS[status] || STATUS.pending;
  return (
    <span className={`badge ${meta.tone} ${size || ''}`}>
      {status === 'running' ? <span className="spin" aria-hidden /> : <span className="dot" aria-hidden />}
      {label || meta.label}
    </span>
  );
}

export function Badge({ tone = 'neutral', children, dot }: { tone?: Tone | 'outline'; children: ReactNode; dot?: boolean }) {
  return <span className={`badge ${tone}`}>{dot && <span className="dot" aria-hidden />}{children}</span>;
}

export function SeverityBadge({ severity }: { severity: string }) {
  if (severity === 'bloqueante') return <Badge tone="critical" dot>Bloqueante</Badge>;
  if (severity === 'informativo') return <Badge tone="info" dot>Informativo</Badge>;
  return <Badge tone="warning" dot>{severity === 'atencao' ? 'Atenção' : 'Alerta'}</Badge>;
}

export function Money({ value, className = '' }: { value: string | number | null | undefined; className?: string }) {
  const negative = Number(value) < 0;
  return <span className={`num nowrap ${negative ? 'neg' : ''} ${className}`}>{money(value)}</span>;
}

export const Percent = ({ value }: { value: string | number | null | undefined }) => <span className="num">{percent(value)}</span>;
export const PP = ({ value }: { value: string | number | null | undefined }) => <span className="num">{pp(value)}</span>;
export const DateBR = ({ value }: { value: string | null | undefined }) => <span className="num">{dateBR(value)}</span>;
export const Count = ({ value }: { value: number | null | undefined }) => <span className="num">{count(value)}</span>;

export function HashChip({ hash, size = 6 }: { hash?: string | null; size?: number }) {
  const [copied, setCopied] = useState(false);
  if (!hash) return <span className="muted">—</span>;
  return (
    <button
      type="button"
      className="hash-chip"
      title={`SHA-256 ${hash} · clique para copiar`}
      onClick={event => {
        event.stopPropagation();
        void navigator.clipboard?.writeText(hash).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1400); });
      }}
    >
      <Icon name={copied ? 'check' : 'hash'} />
      {copied ? 'copiado' : shortHash(hash, size)}
    </button>
  );
}

/** B6 seal: next to any aggregate, opens the rows that compose it. */
export function OriginButton({ onClick, label = 'Ver origem' }: { onClick: () => void; label?: string }) {
  return (
    <button type="button" className="origin-btn" onClick={event => { event.stopPropagation(); onClick(); }} title={label} aria-label={label}>
      <Icon name="origin" />
    </button>
  );
}

export function Empty({ icon = 'check', title, children }: { icon?: IconName; title: string; children?: ReactNode }) {
  return <div className="empty"><Icon name={icon} /><h3>{title}</h3>{children && <p>{children}</p>}</div>;
}

export function Loading({ label = 'Carregando…', page }: { label?: string; page?: boolean }) {
  return <div className={`loading ${page ? 'page' : ''}`}><span className="spin" />{label}</div>;
}

export function Callout({ tone, icon = 'info', children }: { tone?: 'info' | 'warning' | 'critical' | 'good' | 'gate'; icon?: IconName; children: ReactNode }) {
  return <div className={`callout ${tone || ''}`}><Icon name={icon} /><div>{children}</div></div>;
}

export function Tip({ text, children }: { text: ReactNode; children: ReactNode }) {
  return <span className="tip">{children}<span className="tip-bubble" role="tooltip">{text}</span></span>;
}

export function Segmented<T extends string>({ value, options, onChange, size, label }: {
  value: T; options: { value: T; label: ReactNode }[]; onChange: (value: T) => void; size?: 'lg'; label?: string;
}) {
  return (
    <div className={`segmented ${size || ''}`} role="group" aria-label={label}>
      {options.map(option => (
        <button key={option.value} type="button" aria-pressed={option.value === value} onClick={() => onChange(option.value)}>{option.label}</button>
      ))}
    </div>
  );
}

export function Tabs<T extends string>({ value, items, onChange }: {
  value: T; items: { value: T; label: string; count?: number; icon?: IconName }[]; onChange: (value: T) => void;
}) {
  return (
    <div className="tabs" role="tablist">
      {items.map(item => (
        <button key={item.value} type="button" role="tab" aria-selected={item.value === value} className={`tab ${item.value === value ? 'active' : ''}`} onClick={() => onChange(item.value)}>
          {item.icon && <Icon name={item.icon} />}
          {item.label}
          {item.count !== undefined && <span className="count">{count(item.count)}</span>}
        </button>
      ))}
    </div>
  );
}

export function Toggle({ checked, onChange, label, disabled }: { checked: boolean; onChange: (value: boolean) => void; label: string; disabled?: boolean }) {
  return <button type="button" role="switch" className="toggle" aria-checked={checked} aria-label={label} disabled={disabled} onClick={() => onChange(!checked)} />;
}

export function Field({ label, help, children, wide, required }: { label: string; help?: ReactNode; children: ReactNode; wide?: boolean; required?: boolean }) {
  return (
    <label className={`field ${wide ? 'wide' : ''}`}>
      <span>{label}{required && ' *'}</span>
      {children}
      {help && <small>{help}</small>}
    </label>
  );
}

export function PageHead({ eyebrow, title, sub, actions }: { eyebrow?: string; title: ReactNode; sub?: ReactNode; actions?: ReactNode }) {
  return (
    <div className="page-head">
      <div>
        {eyebrow && <p className="eyebrow">{eyebrow}</p>}
        <h1 className="page-title">{title}</h1>
        {sub && <p className="page-sub">{sub}</p>}
      </div>
      {actions && <div className="actions">{actions}</div>}
    </div>
  );
}

export const QUICK_REASONS = ['Contrato assinado', 'Orientação do financeiro', 'Correção de digitação', 'Conferido na fonte original'];

/** Justification with one-click starters: the backend requires a reason for every change. */
export function ReasonInput({ value, onChange, required = true, suggestions = QUICK_REASONS, placeholder }: {
  value: string; onChange: (value: string) => void; required?: boolean; suggestions?: string[]; placeholder?: string;
}) {
  return (
    <div className="stack" style={{ gap: 8 }}>
      <div className="reason-chips">
        {suggestions.map(text => (
          <button key={text} type="button" className="reason-chip" aria-pressed={value.startsWith(text)} onClick={() => onChange(value.startsWith(text) ? value : `${text}${value ? ` · ${value}` : ''}`)}>{text}</button>
        ))}
      </div>
      <textarea className="textarea" value={value} required={required} placeholder={placeholder || 'Descreva o motivo da alteração'} onChange={event => onChange(event.target.value)} rows={2} />
    </div>
  );
}
